-- Apply after cloud-schema.sql and the city/arrangement migrations.
-- Row updates and revision comparison execute in one PostgreSQL transaction.
-- Duplicate legacy media identities must be repaired before these indexes can be created.
begin;
create unique index if not exists trip_item_media_record_identity on public.triptrail_trip_item_media(root_id,id);
create unique index if not exists trip_item_vouchers_record_identity on public.triptrail_trip_item_vouchers(root_id,id);
create unique index if not exists story_entry_media_record_identity on public.triptrail_story_entry_media(root_id,id);
create unique index if not exists story_cover_media_record_identity on public.triptrail_story_cover_media(root_id,id);
create unique index if not exists favorite_media_record_identity on public.triptrail_favorite_media(root_id,id);
create unique index if not exists favorite_vouchers_record_identity on public.triptrail_favorite_vouchers(root_id,id);
create or replace function public.triptrail_patch_record(record_id uuid,record_kind text,record_title text,record_payload jsonb,expected_revision bigint,record_base_payload jsonb)
returns public.triptrail_cloud_records language plpgsql security invoker set search_path='' as $$
declare d jsonb; i jsonb; m jsonb; deleted boolean; result public.triptrail_cloud_records;
begin
perform pg_advisory_xact_lock(hashtextextended(record_kind || ':' || record_id::text,0));
if to_regclass('public.triptrail_deleted_records') is not null then
 execute 'select exists(select 1 from public.triptrail_deleted_records where id=$1 and kind=$2)' into deleted using record_id,record_kind;
 if deleted then raise sqlstate 'PT410' using message='Record is in recycle bin or expired'; end if;
end if;
if record_kind not in ('trip','story','favorite') or jsonb_typeof(record_payload) <> 'object'
   or (record_payload->>'id')::uuid is distinct from record_id or expected_revision < 0
   or record_title is distinct from record_payload->>'title' then
 raise exception 'Invalid cloud record';
end if;
if record_kind='trip' then
delete from public.triptrail_trip_items where root_id=record_id and not (jsonb_path_query_array(record_payload, '$.days[*].items[*].id') ? id::text);
delete from public.triptrail_trip_item_media where root_id=record_id and not (jsonb_path_query_array(record_payload, '$.days[*].items[*].media[*].id') ? id::text);
delete from public.triptrail_trip_item_vouchers where root_id=record_id and not (jsonb_path_query_array(record_payload, '$.days[*].items[*].vouchers[*].id') ? id::text);
if expected_revision = 0 then
        insert into public.triptrail_trips ("id","title","destination","licensePlate","startDate","endDate","note","createdAt") select r."id",r."title",r."destination",r."licensePlate",r."startDate",r."endDate",r."note",r."createdAt" from jsonb_populate_record(null::public.triptrail_trips, record_payload) r on conflict(id) do nothing;
        if not found then raise sqlstate 'PT409' using message='Cloud revision conflict'; end if;
    else
        update public.triptrail_trips t set ("id","title","destination","licensePlate","startDate","endDate","note","createdAt") = (select r."id",r."title",r."destination",r."licensePlate",r."startDate",r."endDate",r."note",r."createdAt" from jsonb_populate_record(null::public.triptrail_trips,record_payload) r),
            revision=t.revision+1, updated_at=now()
        where t.id=record_id and t.revision=expected_revision;
        if not found then raise sqlstate 'PT409' using message='Cloud revision conflict'; end if;
    end if;
delete from public.triptrail_trip_days where root_id=record_id and not (jsonb_path_query_array(record_payload, '$.days[*].id') ? id::text);
for d in select value from jsonb_array_elements(record_payload->'days') loop
insert into public.triptrail_trip_days ("root_id","id","date","title","note","city","sortOrder") select record_id,r."id",r."date",r."title",r."note",r."city",r."sortOrder" from jsonb_populate_record(null::public.triptrail_trip_days, d) r on conflict(root_id,id) do update set "date"=excluded."date","title"=excluded."title","note"=excluded."note","city"=excluded."city","sortOrder"=excluded."sortOrder" where (triptrail_trip_days."date",triptrail_trip_days."title",triptrail_trip_days."note",triptrail_trip_days."city",triptrail_trip_days."sortOrder") is distinct from (excluded."date",excluded."title",excluded."note",excluded."city",excluded."sortOrder");
 for i in select value from jsonb_array_elements(d->'items') loop
insert into public.triptrail_trip_items ("root_id","parent_id","id","title","categoryRaw","startTime","endTime","address","note","locationModeRaw","placeName","placeAddress","originName","originAddress","destinationName","destinationAddress","transportRaw","attractionTypeRaw","distanceText","playDurationMinutes","reservationInfo","cost","isCompleted","executionStatusRaw","isAutomaticCompletionOverridden","isFixedTime","isTimePending","isFavorite","favoriteCity","favoriteCreatedAt","sourceFavoriteID","sortOrder") select record_id,(d->>'id')::uuid,r."id",r."title",r."categoryRaw",r."startTime",r."endTime",r."address",r."note",r."locationModeRaw",r."placeName",r."placeAddress",r."originName",r."originAddress",r."destinationName",r."destinationAddress",r."transportRaw",r."attractionTypeRaw",r."distanceText",r."playDurationMinutes",r."reservationInfo",r."cost",r."isCompleted",r."executionStatusRaw",r."isAutomaticCompletionOverridden",r."isFixedTime",r."isTimePending",r."isFavorite",r."favoriteCity",r."favoriteCreatedAt",r."sourceFavoriteID",r."sortOrder" from jsonb_populate_record(null::public.triptrail_trip_items, i) r on conflict(root_id,id) do update set "parent_id"=excluded."parent_id","title"=excluded."title","categoryRaw"=excluded."categoryRaw","startTime"=excluded."startTime","endTime"=excluded."endTime","address"=excluded."address","note"=excluded."note","locationModeRaw"=excluded."locationModeRaw","placeName"=excluded."placeName","placeAddress"=excluded."placeAddress","originName"=excluded."originName","originAddress"=excluded."originAddress","destinationName"=excluded."destinationName","destinationAddress"=excluded."destinationAddress","transportRaw"=excluded."transportRaw","attractionTypeRaw"=excluded."attractionTypeRaw","distanceText"=excluded."distanceText","playDurationMinutes"=excluded."playDurationMinutes","reservationInfo"=excluded."reservationInfo","cost"=excluded."cost","isCompleted"=excluded."isCompleted","executionStatusRaw"=excluded."executionStatusRaw","isAutomaticCompletionOverridden"=excluded."isAutomaticCompletionOverridden","isFixedTime"=excluded."isFixedTime","isTimePending"=excluded."isTimePending","isFavorite"=excluded."isFavorite","favoriteCity"=excluded."favoriteCity","favoriteCreatedAt"=excluded."favoriteCreatedAt","sourceFavoriteID"=excluded."sourceFavoriteID","sortOrder"=excluded."sortOrder" where (triptrail_trip_items."parent_id",triptrail_trip_items."title",triptrail_trip_items."categoryRaw",triptrail_trip_items."startTime",triptrail_trip_items."endTime",triptrail_trip_items."address",triptrail_trip_items."note",triptrail_trip_items."locationModeRaw",triptrail_trip_items."placeName",triptrail_trip_items."placeAddress",triptrail_trip_items."originName",triptrail_trip_items."originAddress",triptrail_trip_items."destinationName",triptrail_trip_items."destinationAddress",triptrail_trip_items."transportRaw",triptrail_trip_items."attractionTypeRaw",triptrail_trip_items."distanceText",triptrail_trip_items."playDurationMinutes",triptrail_trip_items."reservationInfo",triptrail_trip_items."cost",triptrail_trip_items."isCompleted",triptrail_trip_items."executionStatusRaw",triptrail_trip_items."isAutomaticCompletionOverridden",triptrail_trip_items."isFixedTime",triptrail_trip_items."isTimePending",triptrail_trip_items."isFavorite",triptrail_trip_items."favoriteCity",triptrail_trip_items."favoriteCreatedAt",triptrail_trip_items."sourceFavoriteID",triptrail_trip_items."sortOrder") is distinct from (excluded."parent_id",excluded."title",excluded."categoryRaw",excluded."startTime",excluded."endTime",excluded."address",excluded."note",excluded."locationModeRaw",excluded."placeName",excluded."placeAddress",excluded."originName",excluded."originAddress",excluded."destinationName",excluded."destinationAddress",excluded."transportRaw",excluded."attractionTypeRaw",excluded."distanceText",excluded."playDurationMinutes",excluded."reservationInfo",excluded."cost",excluded."isCompleted",excluded."executionStatusRaw",excluded."isAutomaticCompletionOverridden",excluded."isFixedTime",excluded."isTimePending",excluded."isFavorite",excluded."favoriteCity",excluded."favoriteCreatedAt",excluded."sourceFavoriteID",excluded."sortOrder");for m in select value from jsonb_array_elements(coalesce(nullif(i->'media','null'::jsonb),'[]'::jsonb)) loop
 insert into public.triptrail_trip_item_media ("root_id","parent_id","id","localIdentifier","kindRaw","caption","createdAt","sortOrder","cloudPath") select record_id,(i->>'id')::uuid,r."id",r."localIdentifier",r."kindRaw",r."caption",r."createdAt",r."sortOrder",r."cloudPath" from jsonb_populate_record(null::public.triptrail_trip_item_media, m) r on conflict(root_id,id) do update set "parent_id"=excluded."parent_id","localIdentifier"=excluded."localIdentifier","kindRaw"=excluded."kindRaw","caption"=excluded."caption","createdAt"=excluded."createdAt","sortOrder"=excluded."sortOrder","cloudPath"=excluded."cloudPath" where (triptrail_trip_item_media."parent_id",triptrail_trip_item_media."localIdentifier",triptrail_trip_item_media."kindRaw",triptrail_trip_item_media."caption",triptrail_trip_item_media."createdAt",triptrail_trip_item_media."sortOrder",triptrail_trip_item_media."cloudPath") is distinct from (excluded."parent_id",excluded."localIdentifier",excluded."kindRaw",excluded."caption",excluded."createdAt",excluded."sortOrder",excluded."cloudPath");
end loop;for m in select value from jsonb_array_elements(coalesce(nullif(i->'vouchers','null'::jsonb),'[]'::jsonb)) loop
 insert into public.triptrail_trip_item_vouchers ("root_id","parent_id","id","name","mimeType","dataBase64") select record_id,(i->>'id')::uuid,r."id",r."name",r."mimeType",r."dataBase64" from jsonb_populate_record(null::public.triptrail_trip_item_vouchers, m) r on conflict(root_id,id) do update set "parent_id"=excluded."parent_id","name"=excluded."name","mimeType"=excluded."mimeType","dataBase64"=excluded."dataBase64" where (triptrail_trip_item_vouchers."parent_id",triptrail_trip_item_vouchers."name",triptrail_trip_item_vouchers."mimeType",triptrail_trip_item_vouchers."dataBase64") is distinct from (excluded."parent_id",excluded."name",excluded."mimeType",excluded."dataBase64");
end loop;
 end loop;
end loop;
elsif record_kind='story' then
delete from public.triptrail_story_entry_media where root_id=record_id and not (jsonb_path_query_array(record_payload, '$.entries[*].media[*].id') ? id::text);
if expected_revision = 0 then
        insert into public.triptrail_stories ("id","title","destination","startDate","endDate","summary","createdAt","sourceTripID","syncScopeRaw","sourceSelectionIDsRaw","coverZoom","coverOffsetX","coverOffsetY") select r."id",r."title",r."destination",r."startDate",r."endDate",r."summary",r."createdAt",r."sourceTripID",r."syncScopeRaw",r."sourceSelectionIDsRaw",r."coverZoom",r."coverOffsetX",r."coverOffsetY" from jsonb_populate_record(null::public.triptrail_stories, record_payload) r on conflict(id) do nothing;
        if not found then raise sqlstate 'PT409' using message='Cloud revision conflict'; end if;
    else
        update public.triptrail_stories t set ("id","title","destination","startDate","endDate","summary","createdAt","sourceTripID","syncScopeRaw","sourceSelectionIDsRaw","coverZoom","coverOffsetX","coverOffsetY") = (select r."id",r."title",r."destination",r."startDate",r."endDate",r."summary",r."createdAt",r."sourceTripID",r."syncScopeRaw",r."sourceSelectionIDsRaw",r."coverZoom",r."coverOffsetX",r."coverOffsetY" from jsonb_populate_record(null::public.triptrail_stories,record_payload) r),
            revision=t.revision+1, updated_at=now()
        where t.id=record_id and t.revision=expected_revision;
        if not found then raise sqlstate 'PT409' using message='Cloud revision conflict'; end if;
    end if;
delete from public.triptrail_story_entries where root_id=record_id and not (jsonb_path_query_array(record_payload, '$.entries[*].id') ? id::text);
delete from public.triptrail_story_days where root_id=record_id and not (jsonb_path_query_array(record_payload, '$.days[*].id') ? id::text);
delete from public.triptrail_story_cover_media where root_id=record_id and not (jsonb_path_query_array(record_payload, '$.coverMedia.id') ? id::text);
for d in select value from jsonb_array_elements(record_payload->'days') loop
insert into public.triptrail_story_days ("root_id","id","date","title","note","details","didMigrateInlineSummary","sortOrder","sourceDayID") select record_id,r."id",r."date",r."title",r."note",r."details",r."didMigrateInlineSummary",r."sortOrder",r."sourceDayID" from jsonb_populate_record(null::public.triptrail_story_days, d) r on conflict(root_id,id) do update set "date"=excluded."date","title"=excluded."title","note"=excluded."note","details"=excluded."details","didMigrateInlineSummary"=excluded."didMigrateInlineSummary","sortOrder"=excluded."sortOrder","sourceDayID"=excluded."sourceDayID" where (triptrail_story_days."date",triptrail_story_days."title",triptrail_story_days."note",triptrail_story_days."details",triptrail_story_days."didMigrateInlineSummary",triptrail_story_days."sortOrder",triptrail_story_days."sourceDayID") is distinct from (excluded."date",excluded."title",excluded."note",excluded."details",excluded."didMigrateInlineSummary",excluded."sortOrder",excluded."sourceDayID");
end loop;
for i in select value from jsonb_array_elements(record_payload->'entries') loop
insert into public.triptrail_story_entries ("root_id","id","title","categoryRaw","startTime","endTime","timeLabel","address","supplementalInfo","note","locationModeRaw","placeName","placeAddress","originName","originAddress","destinationName","destinationAddress","transportRaw","attractionTypeRaw","routeInfo","cost","didPrefillSourceMemory","sourceMemoryPrefill","sortOrder","sourceItemID","storyDayID") select record_id,r."id",r."title",r."categoryRaw",r."startTime",r."endTime",r."timeLabel",r."address",r."supplementalInfo",r."note",r."locationModeRaw",r."placeName",r."placeAddress",r."originName",r."originAddress",r."destinationName",r."destinationAddress",r."transportRaw",r."attractionTypeRaw",r."routeInfo",r."cost",r."didPrefillSourceMemory",r."sourceMemoryPrefill",r."sortOrder",r."sourceItemID",r."storyDayID" from jsonb_populate_record(null::public.triptrail_story_entries, i) r on conflict(root_id,id) do update set "title"=excluded."title","categoryRaw"=excluded."categoryRaw","startTime"=excluded."startTime","endTime"=excluded."endTime","timeLabel"=excluded."timeLabel","address"=excluded."address","supplementalInfo"=excluded."supplementalInfo","note"=excluded."note","locationModeRaw"=excluded."locationModeRaw","placeName"=excluded."placeName","placeAddress"=excluded."placeAddress","originName"=excluded."originName","originAddress"=excluded."originAddress","destinationName"=excluded."destinationName","destinationAddress"=excluded."destinationAddress","transportRaw"=excluded."transportRaw","attractionTypeRaw"=excluded."attractionTypeRaw","routeInfo"=excluded."routeInfo","cost"=excluded."cost","didPrefillSourceMemory"=excluded."didPrefillSourceMemory","sourceMemoryPrefill"=excluded."sourceMemoryPrefill","sortOrder"=excluded."sortOrder","sourceItemID"=excluded."sourceItemID","storyDayID"=excluded."storyDayID" where (triptrail_story_entries."title",triptrail_story_entries."categoryRaw",triptrail_story_entries."startTime",triptrail_story_entries."endTime",triptrail_story_entries."timeLabel",triptrail_story_entries."address",triptrail_story_entries."supplementalInfo",triptrail_story_entries."note",triptrail_story_entries."locationModeRaw",triptrail_story_entries."placeName",triptrail_story_entries."placeAddress",triptrail_story_entries."originName",triptrail_story_entries."originAddress",triptrail_story_entries."destinationName",triptrail_story_entries."destinationAddress",triptrail_story_entries."transportRaw",triptrail_story_entries."attractionTypeRaw",triptrail_story_entries."routeInfo",triptrail_story_entries."cost",triptrail_story_entries."didPrefillSourceMemory",triptrail_story_entries."sourceMemoryPrefill",triptrail_story_entries."sortOrder",triptrail_story_entries."sourceItemID",triptrail_story_entries."storyDayID") is distinct from (excluded."title",excluded."categoryRaw",excluded."startTime",excluded."endTime",excluded."timeLabel",excluded."address",excluded."supplementalInfo",excluded."note",excluded."locationModeRaw",excluded."placeName",excluded."placeAddress",excluded."originName",excluded."originAddress",excluded."destinationName",excluded."destinationAddress",excluded."transportRaw",excluded."attractionTypeRaw",excluded."routeInfo",excluded."cost",excluded."didPrefillSourceMemory",excluded."sourceMemoryPrefill",excluded."sortOrder",excluded."sourceItemID",excluded."storyDayID");for m in select value from jsonb_array_elements(coalesce(nullif(i->'media','null'::jsonb),'[]'::jsonb)) loop
 insert into public.triptrail_story_entry_media ("root_id","parent_id","id","localIdentifier","kindRaw","caption","createdAt","sortOrder","cloudPath") select record_id,(i->>'id')::uuid,r."id",r."localIdentifier",r."kindRaw",r."caption",r."createdAt",r."sortOrder",r."cloudPath" from jsonb_populate_record(null::public.triptrail_story_entry_media, m) r on conflict(root_id,id) do update set "parent_id"=excluded."parent_id","localIdentifier"=excluded."localIdentifier","kindRaw"=excluded."kindRaw","caption"=excluded."caption","createdAt"=excluded."createdAt","sortOrder"=excluded."sortOrder","cloudPath"=excluded."cloudPath" where (triptrail_story_entry_media."parent_id",triptrail_story_entry_media."localIdentifier",triptrail_story_entry_media."kindRaw",triptrail_story_entry_media."caption",triptrail_story_entry_media."createdAt",triptrail_story_entry_media."sortOrder",triptrail_story_entry_media."cloudPath") is distinct from (excluded."parent_id",excluded."localIdentifier",excluded."kindRaw",excluded."caption",excluded."createdAt",excluded."sortOrder",excluded."cloudPath");
end loop;
end loop;
if jsonb_typeof(record_payload->'coverMedia')='object' then
insert into public.triptrail_story_cover_media ("root_id","id","localIdentifier","kindRaw","caption","createdAt","sortOrder","cloudPath") select record_id,r."id",r."localIdentifier",r."kindRaw",r."caption",r."createdAt",r."sortOrder",r."cloudPath" from jsonb_populate_record(null::public.triptrail_story_cover_media, record_payload->'coverMedia') r on conflict(root_id,id) do update set "localIdentifier"=excluded."localIdentifier","kindRaw"=excluded."kindRaw","caption"=excluded."caption","createdAt"=excluded."createdAt","sortOrder"=excluded."sortOrder","cloudPath"=excluded."cloudPath" where (triptrail_story_cover_media."localIdentifier",triptrail_story_cover_media."kindRaw",triptrail_story_cover_media."caption",triptrail_story_cover_media."createdAt",triptrail_story_cover_media."sortOrder",triptrail_story_cover_media."cloudPath") is distinct from (excluded."localIdentifier",excluded."kindRaw",excluded."caption",excluded."createdAt",excluded."sortOrder",excluded."cloudPath");
